class ListRepo:
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)


class HardService:
    def __init__(self):
        self.repo = ListRepo()

    def add(self, item):
        self.repo.add(item)

class Service:
    def __init__(self, repo):
        self.repo = repo

    def add(self, item):
        self.repo.add(item.strip().lower())


class FakeRepo:
    def __init__(self):
        self.saved = []

    def add(self, item):
        self.saved.append(item)
